"use client";

import { GrainGradient, MeshGradient } from "@paper-design/shaders-react";
import { useCallback, useState } from "react";
import {
  continueRender,
  delayRender,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type AmbientGradientVariant = "mesh" | "grain";
export type AmbientGradientTheme = "light" | "dark";

/** Blue-tinted light wash derived from the snap-cn accent #266DF0, on #FAFAFA. */
export const AMBIENT_LIGHT_COLORS = [
  "#DCE8FE",
  "#EAF1FE",
  "#F5F8FF",
  "#FAFAFA",
];

/** Deep blue-tinted dark wash derived from #266DF0, on #0A0A0B. */
export const AMBIENT_DARK_COLORS = ["#12203C", "#1B2A4A", "#141417"];

export const AMBIENT_LIGHT_BACK = "#FAFAFA";
export const AMBIENT_DARK_BACK = "#0A0A0B";

/** Mesh distortion above this starts to read as "lava lamp", not ambience. */
export const MAX_MESH_DISTORTION = 0.8;

export interface AmbientPalette {
  colors: string[];
  colorBack: string;
}

/**
 * Pure palette resolver: theme picks the snap-cn wash, explicit `colors` /
 * `colorBack` overrides win per-field.
 */
export function resolveAmbientPalette(
  theme: AmbientGradientTheme,
  colors?: string[],
  colorBack?: string,
): AmbientPalette {
  const themed =
    theme === "dark"
      ? { colors: AMBIENT_DARK_COLORS, colorBack: AMBIENT_DARK_BACK }
      : { colors: AMBIENT_LIGHT_COLORS, colorBack: AMBIENT_LIGHT_BACK };
  return {
    colors: colors && colors.length > 0 ? colors : themed.colors,
    colorBack: colorBack ?? themed.colorBack,
  };
}

/** Clamp mesh distortion to the ambient-safe range [0, MAX_MESH_DISTORTION]. */
export function clampDistortion(value: number): number {
  return Math.min(MAX_MESH_DISTORTION, Math.max(0, value));
}

export interface AmbientGradientProps {
  /** Shader engine: soft mesh blobs or a grainy multi-stop blend. */
  variant?: AmbientGradientVariant;
  /** Palette family. Light and dark washes are both derived from #266DF0. */
  theme?: AmbientGradientTheme;
  /** Override the themed color stops. */
  colors?: string[];
  /** Override the themed base color behind the wash. */
  colorBack?: string;
  /** Drift speed multiplier. 0.5 is a barely-moving ambient wash. */
  speed?: number;
  /** Mesh only: blob distortion, clamped to 0.8. */
  distortion?: number;
  /** Mesh only: rotational swirl of the blobs. */
  swirl?: number;
  /** Grain only: edge softness of the color bands. */
  softness?: number;
  /** Grain only: intensity of the color blend. */
  grainIntensity?: number;
  /** Grain only: film-grain amount over the blend. */
  noise?: number;
  className?: string;
}

/**
 * The flagship "pretty background": one soft ambient color wash driven
 * deterministically by the current frame. Place content on top of it.
 */
export function AmbientGradient({
  variant = "mesh",
  theme = "light",
  colors,
  colorBack,
  speed = 0.5,
  distortion = 0.4,
  swirl = 0.08,
  softness = 0.7,
  grainIntensity = 0.15,
  noise = 0.1,
  className,
}: AmbientGradientProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const palette = resolveAmbientPalette(theme, colors, colorBack);
  const shaderFrame = (frame / fps) * speed * 1000;

  const [handle] = useState(() => delayRender("ambient-gradient"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      {variant === "grain" ? (
        <GrainGradient
          speed={0}
          frame={shaderFrame}
          colors={palette.colors}
          colorBack={palette.colorBack}
          softness={softness}
          intensity={grainIntensity}
          noise={noise}
          fit="cover"
          width={width}
          height={height}
        />
      ) : (
        <MeshGradient
          speed={0}
          frame={shaderFrame}
          colors={palette.colors}
          distortion={clampDistortion(distortion)}
          swirl={swirl}
          fit="cover"
          width={width}
          height={height}
        />
      )}
    </div>
  );
}
